  // ============================================================
  // 六年级 · 课本同步题库（统编版：六上8单元 + 六下6单元）
  // tag 约定：read=课文片段阅读 / acc=日积月累·语文园地，其余为基础与课文理解
  // ============================================================
  function cnRd(q, ans, opts, passage) { const o = mkChoice(q, ans, opts); o.tag = 'read'; o.passage = passage; return o; }
  function cnRdF(q, ans, passage) { const o = mkFill(q, ans); o.tag = 'read'; o.passage = passage; return o; }
  function cnAcc(q, ans, opts) { const o = mkChoice(q, ans, opts); o.tag = 'acc'; return o; }
  function cnAccF(q, ans) { const o = mkFill(q, ans); o.tag = 'acc'; return o; }
  function cnAccJ(q, ans) { const o = mkJudge(q, ans); o.tag = 'acc'; return o; }

  // ---- 六上第一单元：草原 / 丁香结 / 古诗词三首 / 花之歌 ----
  function cn6t1_pool() {
    const qs = [];
    qs.push(mkChoice('《草原》中"渲染"的"渲"读音是？', 'xuàn', ['xuān', 'xuǎn', 'xuèn']));
    qs.push(mkChoice('"蒙古包"的"蒙"在这里读？', 'měng', ['méng', 'mēng', 'mén']));
    qs.push(mkChoice('"勾勒"的"勒"读音是？', 'lè', ['lēi', 'lèi', 'liē']));
    qs.push(mkChoice('《花之歌》中"参差"一词的读音是？', 'cēn cī', ['cān chā', 'shēn cī', 'cēn chà']));
    qs.push(mkChoice('"愁怨"的"怨"读音是？', 'yuàn', ['yuān', 'yùn', 'yuán']));
    qs.push(mkChoice('下列词语书写正确的一项是？', '一碧千里', ['一壁千里', '一碧千理', '衣碧千里']));
    qs.push(mkFill('《草原》的作者是____。', '老舍'));
    qs.push(mkChoice('"薄雾"的"薄"读音是？', 'bó', ['báo', 'bò', 'bù']));
    qs.push(mkChoice('《草原》按什么顺序记叙？', '初见草原—迎客—联欢—话别', ['初见草原—话别—联欢—迎客', '迎客—初见草原—话别—联欢', '联欢—初见草原—迎客—话别']));
    qs.push(mkFill('《草原》中"蒙汉情深何忍别"的下一句是"____"。', '天涯碧草话斜阳'));
    qs.push(mkChoice('《丁香结》的作者是？', '宗璞', ['老舍', '冰心', '巴金']));
    qs.push(mkChoice('在《丁香结》中，丁香"结"象征什么？', '生活中解不开的愁怨', ['丰收的喜悦', '友谊的象征', '春天的来临']));
    qs.push(mkChoice('《花之歌》的作者纪伯伦是哪个国家的诗人？', '黎巴嫩', ['中国', '法国', '印度']));
    qs.push(mkChoice('《花之歌》采用什么口吻来写？', '以花的口吻自述', ['第三人称旁观', '以风的口吻', '以云的口吻']));
    qs.push(mkChoice('《宿建德江》的作者是？', '孟浩然', ['王维', '李白', '杜甫']));
    qs.push(mkFill('《六月二十七日望湖楼醉书》的作者是____。', '苏轼'));
    qs.push(mkFill('《西江月·夜行黄沙道中》的作者是____。', '辛弃疾'));
    qs.push(mkChoice('"移舟泊烟渚"的下一句是？', '日暮客愁新', ['野旷天低树', '江清月近人', '明月别枝惊鹊']));
    qs.push(mkChoice('"黑云翻墨未遮山"出自？', '六月二十七日望湖楼醉书', ['宿建德江', '西江月·夜行黄沙道中', '过故人庄']));
    qs.push(mkChoice('《西江月·夜行黄沙道中》描写的是哪个季节的景色？', '夏天', ['春天', '秋天', '冬天']));
    qs.push(cnRd('《草原》片段中，作者把草原比作什么？', '无边的绿毯', ['白色的大海', '金色的麦浪', '蓝色的天空'], '这次，我看到了草原。那里的天比别处的更可爱，空气是那么清鲜，天空是那么明朗，使我总想高歌一曲，表示我满心的愉快。在天底下，一碧千里，而并不茫茫。'));
    qs.push(cnRd('片段中"一碧千里"形容的是？', '草原辽阔碧绿', ['天空高远', '空气清新', '心情愉快'], '这次，我看到了草原。那里的天比别处的更可爱，空气是那么清鲜，天空是那么明朗，使我总想高歌一曲，表示我满心的愉快。在天底下，一碧千里，而并不茫茫。'));
    qs.push(cnRd('片段中"使我总想高歌一曲"表达了作者怎样的心情？', '满心的愉快', ['淡淡的忧愁', '愤怒不满', '紧张害怕'], '这次，我看到了草原。那里的天比别处的更可爱，空气是那么清鲜，天空是那么明朗，使我总想高歌一曲，表示我满心的愉快。在天底下，一碧千里，而并不茫茫。'));
    qs.push(cnRd('这个片段先写什么，再写什么？', '先写天空，再写地面', ['先写地面，再写天空', '只写天空', '只写地面'], '这次，我看到了草原。那里的天比别处的更可爱，空气是那么清鲜，天空是那么明朗，使我总想高歌一曲，表示我满心的愉快。在天底下，一碧千里，而并不茫茫。'));
    qs.push(cnRd('《丁香结》片段中，丁香花是什么颜色？', '白、紫', ['红、黄', '蓝、绿', '黑、灰'], '今年的丁香花似乎开得格外茂盛，城里城外，都是一样。城里街旁，忽然呈出两片雪白，顿使人眼前一亮，再仔细看，才知是两行丁香花。有的宅院里探出半树银妆，星星般的小花缀满枝头，从墙上窥着行人，惹得人走过了还要回头望。'));
    qs.push(cnRd('片段中"星星般的小花缀满枝头"运用了什么修辞？', '比喻', ['拟人', '夸张', '反问'], '今年的丁香花似乎开得格外茂盛，城里城外，都是一样。城里街旁，忽然呈出两片雪白，顿使人眼前一亮，再仔细看，才知是两行丁香花。有的宅院里探出半树银妆，星星般的小花缀满枝头，从墙上窥着行人，惹得人走过了还要回头望。'));
    qs.push(cnRd('"从墙上窥着行人"中的"窥"字，把丁香花写得像什么？', '像调皮的孩子', ['像威严的将军', '像冷漠的过客', '像飞行的鸟儿'], '今年的丁香花似乎开得格外茂盛，城里城外，都是一样。城里街旁，忽然呈出两片雪白，顿使人眼前一亮，再仔细看，才知是两行丁香花。有的宅院里探出半树银妆，星星般的小花缀满枝头，从墙上窥着行人，惹得人走过了还要回头望。'));
    qs.push(cnRd('从片段看，丁香花给作者的感受是？', '惹人喜爱', ['令人害怕', '让人讨厌', '毫无感觉'], '今年的丁香花似乎开得格外茂盛，城里城外，都是一样。城里街旁，忽然呈出两片雪白，顿使人眼前一亮，再仔细看，才知是两行丁香花。有的宅院里探出半树银妆，星星般的小花缀满枝头，从墙上窥着行人，惹得人走过了还要回头望。'));
    qs.push(cnAcc('《过故人庄》中"绿树村边合"的下一句是？', '青山郭外斜', ['开轩面场圃', '把酒话桑麻', '待到重阳日']));
    qs.push(cnAcc('《过故人庄》的作者是？', '孟浩然', ['王维', '李白', '白居易']));
    qs.push(cnAcc('本单元习作《变形记》要求写成什么体裁？', '想象作文', ['写实日记', '说明文', '议论文']));
    qs.push(cnAccJ('借景抒情就是把情感直接喊出来。', false));
    return qs;
  }

