    qs.push(mkChoice('《开国大典》的"阅兵式"场面运用了什么写法？', '点面结合', ['先抑后扬', '托物言志', '首尾呼应']));
    qs.push(mkChoice('《灯光》中，郝副营长为了什么而牺牲？', '为后续部队照亮前进道路', ['为了侦察敌情', '为了转移群众', '为了运送物资']));
