    qs.push(cnRd('《桥》片段中，老汉"像一座山"说明他？', '镇定威严，是群众的依靠', ['身体很胖', '站得高', '面无表情'], '木桥前，没腿深的水里，站着他们的党支部书记，那个全村人都拥戴的老汉。老汉清瘦的脸上淌着雨水。他不说话，盯着乱哄哄的人们。他像一座山。人们停住脚，望着老汉。老汉沙哑地喊话："桥窄！排成一队，不要挤！党员排在后边！"'));
