    qs.push(cnRd('"他不说话，盯着乱哄哄的人们"中的"盯"字表现了老汉的？', '威严和责任感', ['好奇', '害怕', '无奈'], '木桥前，没腿深的水里，站着他们的党支部书记，那个全村人都拥戴的老汉。老汉清瘦的脸上淌着雨水。他不说话，盯着乱哄哄的人们。他像一座山。人们停住脚，望着老汉。老汉沙哑地喊话："桥窄！排成一队，不要挤！党员排在后边！"'));
    qs.push(cnRd('《穷人》片段中，桑娜"忐忑不安地想"主要因为？', '收养孤儿怕丈夫不同意，生活更艰难', ['担心孩子考试', '害怕邻居发现', '担心船翻了'], '桑娜脸色苍白，神情激动。她忐忑不安地想："他会说什么呢？这是闹着玩的吗？自己的五个孩子已经够他受的了……是他来啦？……不，还没来！……为什么把他们抱过来啊？……他会揍我的！那也活该，我自作自受……嗯，揍我一顿也好！"'));
