    qs.push(mkChoice('语文园地·日积月累"五行"指的是？', '金木水火土', ['金银铜铁锡', '东西南北中', '红黄蓝绿黑']));
    qs.push(mkChoice('"五谷"指的是？', '稻麦黍菽稷', ['稻米面油盐', '酸甜苦辣咸', '宫商角徵羽']));
