    qs.push(cnRd('《盼》片段中，"我"为什么兴奋？', '因为盼了很久的雨终于要来了', ['因为要放学了', '因为捡到钱', '因为要过生日'], '有一天，快到家时，路边的小杨树忽然沙啦啦地喧闹起来，就像在嘻嘻地笑。我放慢了脚步，心想，雨点儿打在头上，才是世界上最美的事呢！果然，随着几声闷雷，头顶上真的落上了几个雨点儿。我又仰起头来，甩打着书包就大步跑进了楼门。'));
