    qs.push(cnRd('《青山不老》片段中，院子里的景象是？', '绿树成荫，一片葱茏', ['一片荒凉', '满是垃圾', '黄沙漫天'], '窗外是参天的杨柳。院子在山沟里，山上全是树。我们盘腿坐在土炕上，就像坐在船上，四周全是绿色的波浪，风一吹，树梢卷过涛声，叶间闪着粼粼的波光。'));
    qs.push(cnRd('片段中"四周全是绿色的波浪"说明？', '树木茂盛，满山是树', ['山上有水', '风很大', '有海啸'], '窗外是参天的杨柳。院子在山沟里，山上全是树。我们盘腿坐在土炕上，就像坐在船上，四周全是绿色的波浪，风一吹，树梢卷过涛声，叶间闪着粼粼的波光。'));
    qs.push(cnRd('"叶间闪着粼粼的波光"运用了比喻，把什么比作波光？', '阳光透过树叶的光影', ['海水', '露珠', '雪花'], '窗外是参天的杨柳。院子在山沟里，山上全是树。我们盘腿坐在土炕上，就像坐在船上，四周全是绿色的波浪，风一吹，树梢卷过涛声，叶间闪着粼粼的波光。'));
    qs.push(cnRd('这段描写衬托出老人的什么？', '植树造林的功绩，改造荒山的成就', ['生活很舒服', '家里很有钱', '喜欢划船'], '窗外是参天的杨柳。院子在山沟里，山上全是树。我们盘腿坐在土炕上，就像坐在船上，四周全是绿色的波浪，风一吹，树梢卷过涛声，叶间闪着粼粼的波光。'));
    qs.push(cnAcc('"九曲黄河万里沙"中的"九曲"形容？', '河道弯曲很多', ['有九条河', '黄河长九里', '黄河是直的']));
