    qs.push(cnRd('《少年闰土》片段中，闰土在什么环境下刺猹？', '深蓝的天空下、海边的沙地上', ['下雨天', '雪地里', '树林里'], '深蓝的天空中挂着一轮金黄的圆月，下面是海边的沙地，都种着一望无际的碧绿的西瓜。其间有一个十一二岁的少年，项带银圈，手捏一柄钢叉，向一匹猹尽力地刺去。那猹却将身一扭，反从他的胯下逃走了。'));
    qs.push(cnRd('片段中闰土的装束和动作，表现了他？', '健康、勇敢、机敏', ['体弱多病', '胆小', '懒惰'], '深蓝的天空中挂着一轮金黄的圆月，下面是海边的沙地，都种着一望无际的碧绿的西瓜。其间有一个十一二岁的少年，项带银圈，手捏一柄钢叉，向一匹猹尽力地刺去。那猹却将身一扭，反从他的胯下逃走了。'));
    qs.push(cnRd('"那猹却将身一扭，反从他的胯下逃走了"写出了猹的？', '狡猾机灵', ['凶猛', '笨拙', '温顺'], '深蓝的天空中挂着一轮金黄的圆月，下面是海边的沙地，都种着一望无际的碧绿的西瓜。其间有一个十一二岁的少年，项带银圈，手捏一柄钢叉，向一匹猹尽力地刺去。那猹却将身一扭，反从他的胯下逃走了。'));
    qs.push(cnRd('这个片段是"我"对什么的回忆？', '月下看瓜刺猹的闰土', ['海边日出', '雪地捕鸟', '听故事'], '深蓝的天空中挂着一轮金黄的圆月，下面是海边的沙地，都种着一望无际的碧绿的西瓜。其间有一个十一二岁的少年，项带银圈，手捏一柄钢叉，向一匹猹尽力地刺去。那猹却将身一扭，反从他的胯下逃走了。'));
    qs.push(cnRd('《我的伯父鲁迅先生》片段中，"碰壁"指的是？', '旧社会对进步的迫害打击', ['真的撞到墙壁', '鼻子受伤', '走路摔倒'], '有一次，在伯父家里，大伙儿围着一张桌子吃晚饭。我望望爸爸的鼻子，又望望伯父的鼻子，说："大伯，您跟爸爸哪儿都像，就是有一点不像。""哪一点不像呢？"伯父转过头来，微笑着问我。他嘴里嚼着，嘴唇上的胡子跟着一动一动的。"爸爸的鼻子又高又直，您的呢，又扁又平。"我看了他们半天才说。"你不知道，"伯父摸了摸自己的鼻子，笑着说，"我小的时候，鼻子跟你爸爸的一样，也是又高又直的。""那怎么——""可是到了后来，碰了几次壁，把鼻子碰扁了。"'));
